-- DiveFriend: tabel spots di Supabase (sumber data online, sinkron SATU ARAH ke SQLite di HP).
-- Cara pakai: Supabase Dashboard > SQL Editor > New query > tempel seluruh isi file ini > Run.
-- Aman dijalankan berulang kali: tabel dibuat hanya kalau belum ada, data di-upsert berdasarkan id.
-- Isi data diambil dari lib/data/seed/spots_seed.dart (spotsSeedVersion 10), lengkap dengan sumbernya.

create table if not exists public.spots (
  id text primary key,
  name text not null,
  region text not null,
  level text not null check (level in ('pemula', 'menengah', 'lanjutan')),
  level_basis text not null,
  types text[] not null,
  tagline text not null,
  summary text not null,
  depth_text text,
  best_season text,
  biota text[] not null default '{}',
  price_idr integer check (price_idr is null or price_idr > 0),
  latitude double precision,
  longitude double precision,
  time_zone text,
  sources text[] not null,
  photo_url text,
  photo_credit text,
  photo_license text,
  photo_source_url text,
  updated_at timestamptz not null default now()
);

-- Keamanan: aplikasi di HP hanya boleh MEMBACA. Tidak ada kebijakan insert, update, atau delete,
-- jadi siapa pun yang memegang kunci publik tidak bisa mengubah data. Mengubah data hanya lewat dashboard.
alter table public.spots enable row level security;

drop policy if exists "spots dibaca semua orang" on public.spots;
create policy "spots dibaca semua orang"
  on public.spots
  for select
  to anon, authenticated
  using (true);

grant select on public.spots to anon, authenticated;

insert into public.spots (id, name, region, level, level_basis, types, tagline, summary, depth_text, best_season, biota, price_idr, latitude, longitude, time_zone, sources, photo_url, photo_credit, photo_license, photo_source_url)
values
  ('bunaken', 'Taman Nasional Bunaken', 'Sulawesi Utara', 'pemula', 'Estimasi sementara tim, belum ada sumber penilaian level. Perlu ditinjau.', array['scuba', 'snorkeling']::text[], 'Dinding karang yang jatuh lurus ke laut dalam di jantung Segitiga Terumbu Karang.', 'Taman Nasional Bunaken ada di utara Sulawesi, dekat Manado, dan menjadi salah satu taman laut paling terkenal di Indonesia. Lautnya mencakup 97 persen dari total luas sekitar 890 km2, sisanya lima pulau yaitu Bunaken, Manado Tua, Mantehage, Nain, dan Siladen.

Daya tarik utamanya ada di bawah air. Kawasan ini tidak punya paparan benua, jadi pantainya langsung turun ke lereng benua dan membentuk dinding karang vertikal setinggi 25 sampai 50 meter. Di dinding itu hidup 13 genus karang. Secara keseluruhan tercatat sekitar 390 spesies karang dan kira-kira 2.000 spesies ikan, dengan suhu air yang nyaman di kisaran 27 sampai 29 derajat Celsius.

Penyelam bisa berjumpa kima raksasa, ikan malaikat kaisar, kuda laut, sampai nautilus. Pada 2009, ikan purba selakanta Indonesia bahkan pertama kali terekam langsung di alam dekat Manado Tua. Buat yang tidak menyelam, snorkeling juga jadi kegiatan utama di sini.', 'Umumnya 5-40 m (dinding karang setinggi 25-50 m)', 'Sepanjang tahun, terbaik April-Oktober (kemarau)', array['Kima raksasa (7 dari 8 spesies dunia)', 'Ikan malaikat kaisar', 'Kuda laut tutul', 'Kuda laut pigmi', 'Nautilus berongga', 'Selakanta Indonesia', 'Penyu', 'Barakuda', 'Kuwe', 'Napoleon wrasse', 'Bumphead parrotfish', 'Frogfish']::text[], 1500000, 1.667, 124.65, 'WITA', array['Wikipedia: Bunaken National Park (luas, dinding karang, keanekaragaman) - https://en.wikipedia.org/wiki/Bunaken_National_Park', 'Wikipedia: Bunaken (suhu air, kima raksasa) - https://en.wikipedia.org/wiki/Bunaken', 'UNESCO Tentative List (dasar laut curam) - https://whc.unesco.org/en/tentativelists/2002', 'Two Fish Divers (menyelam dan snorkeling) - https://oldsite.twofishdivers.com/?p=21104', 'National-Parks.org (penyu) - https://national-parks.org/indonesia/bunaken-national-park/', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Underwater Asia: Bunaken (musim, biota) - https://underwaterasia.info/indonesia/bunaken-national-park-dive-guide', 'Zublu Diving (musim terbaik) - https://zubludiving.com/destination/indonesia/sulawesi/bunaken-manado', 'Bluewater Dive Travel (kedalaman, visibilitas) - https://www.bluewaterdivetravel.com/eco-divers-manado', 'Champion Traveler (musim hujan) - https://championtraveler.com/dates/best-time-to-visit-bunaken-id/']::text[], 'https://img.cnt.traveloka.com/tvlk/blog/2020/01/keindahan-alam-indonesia-5-Super-Adventure.jpg?tr=q-70,c-at_max,w-500,h-250,dpr-2', null, null, 'https://www.traveloka.com/id-id/explore/destination/taman-nasional-bunaken-surga-bawah-laut-di-sulawesi-utara-acc/180596'),
  ('wakatobi', 'Wakatobi', 'Sulawesi Tenggara', 'pemula', 'Arus umumnya ringan dan banyak titik selam cocok untuk semua level (PADI).', array['scuba']::text[], 'Sekitar 150 pulau dengan terumbu karang yang jadi prioritas utama konservasi laut Indonesia.', 'Nama Wakatobi berasal dari empat pulau utamanya, yaitu Wangi-wangi, Kaledupa, Tomia, dan Binongko. Gugusan sekitar 150 pulau ini ada di Sulawesi Tenggara dan menjadi bagian dari Segitiga Terumbu Karang. Daratan kabupatennya hanya 473,62 km2, sementara perairannya membentang sekitar 17.554 km2.

Taman Nasional Wakatobi seluas sekitar 1,39 juta hektare dan termasuk prioritas tertinggi konservasi laut di Indonesia. Bentang bawah lautnya beragam, mulai dari atol, dinding, gunung laut, sampai karang penghalang. Titik terdalam perairannya sekitar 1.044 meter.

UNESCO memasukkan Wakatobi ke Jaringan Cagar Biosfer Dunia pada Juli 2012. Di daratan ada Benteng Liya yang berdinding empat lapis, dan suku Bajau, pengembara laut yang hidupnya bergantung pada laut, juga tinggal di sini.', 'Titik populer sekitar 0-60 m (Roma 5-25 m)', 'Sepanjang tahun (kemarau Mei-Oktober, paling basah Januari-Februari)', array['Penyu', 'Pari', 'Hiu', 'Mandarinfish (saat senja)', 'Kipas gorgonia raksasa (lebih dari 2 m)', 'Karang hitam', 'Cuttlefish', 'Nudibranch', 'Ikan unicorn', 'Clownfish dan anemon']::text[], 3000000, -5.53583, 123.75806, 'WITA', array['Wikipedia: Wakatobi Regency (koordinat, luas, cagar biosfer, Benteng Liya) - https://en.wikipedia.org/wiki/Wakatobi_Regency', 'Underwater Asia (jenis lanskap selam) - https://dev.underwaterasia.info/countries/indonesia', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Scuba Diver Life (kedalaman titik selam) - https://scubadiverlife.com/all-the-best-of-wakatobi/', 'PADI: Guide to Diving in Wakatobi (arus, level, biota) - https://blog.padi.com/guide-to-diving-in-wakatobi/', 'Original Diving (musim) - https://www.originaldiving.com/far-east/indonesia/dive-wakatobi/best-time', 'Dive The World (hujan dan visibilitas) - https://dive-the-world.com/diving-sites-indonesia-wakatobi.php', 'Deeper Blue (biota dan titik selam) - https://www.deeperblue.com/top-5-favorite-dives-at-wakatobi/']::text[], 'https://backpackerjakarta.com/wp-content/uploads/2017/07/Wakatobi-Dive-Resort_photo-by-Didi-Lotze.jpg', null, null, 'https://backpackerjakarta.com/taman-nasional-wakatobi-salah-satu-surga-bawah-laut-indonesia-yang-mendunia/'),
  ('raja-ampat', 'Raja Ampat', 'Papua Barat Daya', 'lanjutan', 'Ada titik dangkal untuk pemula yang percaya diri, tetapi arus kuat sehingga kualifikasi selam lanjutan disarankan (DIVESSI).', array['scuba']::text[], 'Kepulauan terpencil di ujung barat laut Papua yang dijuluki pusat keanekaragaman laut tropis dunia.', 'Raja Ampat berarti Empat Raja. Kepulauan ini ada di ujung barat laut Semenanjung Kepala Burung, Pulau Papua, dan sejak 2024 masuk Provinsi Papua Barat Daya. Isinya lebih dari 1.500 pulau kecil, karang, dan gosong di sekitar empat pulau utama yaitu Misool, Salawati, Batanta, dan Waigeo, ditambah Pulau Kofiau.

Di bawah air, Raja Ampat termasuk yang terkaya di dunia. Tercatat lebih dari 600 spesies karang keras, sekitar 75 persen dari seluruh spesies karang dunia, dan lebih dari 1.700 spesies ikan karang. Dugong, paus, lumba-lumba, dan hiu paus juga hidup di perairannya. Suhu air di bagian utara 28 sampai 30 derajat Celsius, sedangkan di selatan (Misool) 26 sampai 28 derajat Celsius.

Lokasinya terpencil dan relatif jauh dari keramaian, jadi banyak penyelam datang lewat kapal liveaboard. Sejak 2025, kepulauan ini juga berstatus cagar biosfer UNESCO.', 'Titik populer sekitar 5-30 m', 'Oktober-April (kemarau, laut tenang), selam bagus sepanjang tahun', array['Karang keras (lebih dari 600 spesies)', 'Ikan karang (lebih dari 1.700 spesies)', 'Pari manta', 'Hiu paus', 'Dugong', 'Penyu belimbing, lekang, dan sisik']::text[], 3000000, -0.2333115, 130.5078908, 'WIT', array['Wikipedia: Raja Ampat Islands (koordinat, keanekaragaman, status) - https://www.wikipedia.org/wiki/Raja_Ampat', 'Underwater Asia (liveaboard, kualitas selam) - https://dev.underwaterasia.info/countries/indonesia', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'DUNE (musim, angin, Misool) - https://dune-world.com/en/articles/best-time-to-dive-indonesia-season-guide', 'Eskimo Travel (musim terbaik) - https://www.eskimo.travel/en/blog/best-diving-spots-in-indonesia', 'Yacht Charter Indonesia (kedalaman titik selam) - https://yachtcharterindonesia.com/diving-in-raja-ampat/', 'DIVESSI (titik dangkal, arus kuat) - https://www.divessi.com/en/blog/best-diving-in-asia-8626.html']::text[], 'https://upload.wikimedia.org/wikipedia/commons/8/88/Raja_Ampat%2C_Mutiara_Indah_di_Timur_Indonesia.jpg?utm_source=commons.wikimedia.org&utm_campaign=index&utm_content=original', 'I Made Adi Dharmawam', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Raja_Ampat,_Mutiara_Indah_di_Timur_Indonesia.jpg'),
  ('komodo', 'Taman Nasional Komodo', 'Nusa Tenggara Timur', 'lanjutan', 'Banyak titik terkenal (Batu Bolong, Castle Rock) berarus kuat dan disarankan untuk penyelam lanjut, sementara Manta Point cocok untuk pemula (DiveSSI, Eskimo Travel).', array['scuba', 'snorkeling']::text[], 'Rumah biawak komodo dengan perairan berarus yang kaya pari manta, hiu, dan penyu.', 'Taman Nasional Komodo berada di antara Pulau Sumbawa dan Flores, di perbatasan Nusa Tenggara Timur dan Nusa Tenggara Barat. Taman ini berdiri pada 1980 untuk melindungi komodo, kadal terbesar di dunia, lalu diperluas pada 1984 menjadi 219.322 hektare dengan area laut yang lebih luas dan sebagian daratan Flores. Sekitar 60 persen kawasannya adalah laut, dan taman ini juga berstatus Warisan Dunia UNESCO.

Pulau-pulaunya berasal dari gunung api dan perairannya termasuk Segitiga Terumbu Karang. Habitat lautnya beragam, mulai dari terumbu karang, mangrove, padang lamun, gunung laut, sampai teluk semi tertutup. Tercatat lebih dari 1.000 spesies ikan, sekitar 260 spesies karang pembentuk terumbu, dan 70 spesies spons. Pari manta, hiu, dugong, lumba-lumba, dan penyu juga menjadi penghuninya.

Perairannya disebut disapu arus dan kaya satwa pelagis, jadi cocok untuk penyelam yang sudah nyaman dengan arus. Menyelam bisa dilakukan sepanjang tahun.', 'Titik populer sekitar 4-35 m (Batu Bolong sampai lebih dari 70 m)', 'April-November (kemarau), bisa sepanjang tahun', array['Pari manta', 'Hiu karang abu-abu dan sirip putih', 'Barakuda', 'Kuwe raksasa', 'Penyu', 'Pari elang', 'Kima raksasa', 'Lumba-lumba', 'Dugong']::text[], 2000000, -8.54333, 119.48944, 'WITA', array['Wikipedia: Komodo National Park (koordinat, 1980, zona laut) - https://en.wikipedia.org/wiki/Komodo_National_Park', 'UNESCO World Heritage: Komodo (perluasan 1984, 219.322 ha) - https://whc.unesco.org/document/153875', 'Dive The World (keanekaragaman, menyelam sepanjang tahun) - https://www.dive-the-world.com/reefs-and-parks-indonesia-komodo-national-park.php', 'Aqua Expeditions (habitat laut) - https://www.aquaexpeditions.com/indonesia-cruise/komodo-islands/', 'Underwater Asia (arus, satwa pelagis) - https://dev.underwaterasia.info/countries/indonesia', 'Luxury Hunt (menyelam dan snorkeling) - https://www.luxuryhunt.com/sleep/indonesia/alila-purnama/', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Dive Tribe Komodo (kedalaman titik selam) - https://divetribekomodo.com/faq/about-komodo-dive-sites/top-10-dive-sites-komodo-national-park', 'DiveSSI: Komodo (level, arus) - https://www.divessi.com/en/mydiveguide/divesite/77789', 'Komodo Resort (musim terbaik) - https://www.komodoresort.com/de/indonesia-diving', 'Eskimo Travel (drift dive, musim) - https://www.eskimo.travel/en/blog/best-diving-spots-in-indonesia', 'La Galigo Liveaboard (musim, manta) - https://www.lagaligoliveaboard.com/best-komodo-dive-sites-to-visit/']::text[], 'https://suarapemerintah.id/wp-content/uploads/2022/02/pulau-padar-1068x712.webp', null, null, 'https://suarapemerintah.id/2022/02/ke-taman-nasional-komodo-wajib-abadikan-6-spot-instagenic-ini/'),
  ('karimunjawa', 'Kepulauan Karimunjawa', 'Jawa Tengah', 'pemula', 'Kegiatan utamanya snorkeling di sekitar pulau (Jakarta Post). Estimasi tim, perlu ditinjau.', array['snorkeling']::text[], '27 pulau di Laut Jawa, cocok untuk snorkeling dan berjumpa penyu.', 'Karimunjawa adalah gugusan 27 pulau di Laut Jawa, sekitar 80 km di barat laut Jepara, Jawa Tengah. Total daratannya 45,62 km2. Pulau utamanya Karimun seluas 2.700 hektare, dan yang terbesar kedua adalah Kemujan dengan 1.400 hektare. Sekitar 9.800 orang tinggal di lima pulau (9.789 jiwa pada Sensus 2020).

Dua puluh dua pulau di sini dilindungi sebagai kawasan konservasi laut Taman Nasional Karimunjawa. Pulau-pulaunya dikelilingi terumbu karang tepi dan terumbu yang tersebar, ditambah padang lamun. Penyu sisik dan penyu hijau bisa ditemukan di perairannya.

Budaya Jawa mendominasi kehidupan pulau, dan ini satu-satunya gugusan pulau lepas pantai Jawa yang berbahasa pengantar Jawa. Wisatawan biasanya menyewa perahu untuk keliling pulau dan snorkeling.', 'Perairan snorkeling di sekitar hampir semua pulau', 'April-Oktober (kemarau)', array['Penyu sisik', 'Penyu hijau', 'Hiu (sering terlihat)', 'Padang lamun']::text[], 1200000, -5.81917, 110.459, 'WIB', array['Wikipedia: Karimunjawa (koordinat, luas, penduduk) - https://en.wikipedia.org/wiki/Karimunjawa', 'Wikipedia: Karimunjawa National Park (penyu, lamun) - https://en.wikipedia.org/wiki/Karimunjawa_National_Park', 'Kemenparekraf (snorkeling, perahu) - https://bob.kemenparekraf.go.id/en/1927-pulau-karimunjawa', 'DBpedia (zona waktu UTC+7) - https://dbpedia.org/page/Karimunjawa', 'Jakarta Post: Charm of the Karimun Jawa Islands (musim, snorkeling) - https://www.thejakartapost.com/news/2012/12/09/charm-karimun-jawa-islands', 'Traveloka (musim kemarau dan hujan) - https://www.traveloka.com/en-id/destination/area/karimunjawa-106983', 'Indonesia Expat (titik snorkeling, hiu) - https://indonesiaexpat.biz/travel/8-reasons-to-visit-karimunjawa', 'Zona waktu: UTC+7 (WIB), tertulis di Wikipedia Karimunjawa.']::text[], 'https://statik.tempo.co/data/2019/07/30/id_859623/859623_720.jpg', null, null, 'https://www.tempo.co/hiburan/4-keunikan-kepulauan-karimunjawa-nan-eksotis-302277'),
  ('derawan', 'Kepulauan Derawan', 'Kalimantan Timur', 'menengah', 'Titik dekat Pulau Derawan mudah dan berarus ringan (Liveaboard.com), tetapi Kakaban dan Maratua punya tebing curam dan arus kuat (Zublu).', array['scuba']::text[], '31 pulau tempat penyu hijau bertelur dan ubur-ubur tak menyengat berenang bebas.', 'Kepulauan Derawan terdiri dari 31 pulau di Laut Sulawesi, Kabupaten Berau, Kalimantan Timur. Yang paling dikenal adalah Derawan, Kakaban, Maratua, dan Sangalaki. Kawasan ini bagian dari Segitiga Terumbu Karang dengan 872 spesies ikan karang serta 507 spesies karang dan invertebrata. Satwa dilindungi seperti lima spesies kima raksasa, dua spesies penyu, dan kepiting kelapa juga hidup di sini.

Derawan punya lokasi bertelur penyu hijau terbesar di Indonesia. Di Pulau Kakaban ada danau berisi jutaan ubur-ubur tak menyengat, dan ada danau serupa di Maratua. Pulau Maratua seluas 35,5 km2 juga menyimpan setidaknya 13 gua yang tersambung ke laut.

Hanya dua pulau yang berpenghuni, yaitu Derawan dan Maratua. Ada tiga resor selam di kepulauan ini, dan Bandara Maratua dengan landasan 1.200 meter beroperasi sejak September 2015.', 'Sangalaki dan Kakaban sekitar 15-25 m, Maratua 15-30 m lebih', 'Sepanjang tahun, terbaik sekitar Maret-Oktober (Januari bisa badai)', array['Pari manta (Sangalaki)', 'Penyu hijau dan sisik', 'Dugong', 'Ubur-ubur tak menyengat (Kakaban)', 'Bumphead parrotfish', 'Napoleon wrasse', 'Kuda laut pigmi', 'Mandarin fish', 'Cumi flamboyan', 'Hiu karang (kadang hiu martil)', 'Kepiting kelapa']::text[], 2000000, 2.283, 118.217, 'WITA', array['Wikipedia: Derawan Islands (semua data kepulauan) - https://en.wikipedia.org/wiki/Derawan_Islands', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Zublu Diving: Derawan (musim, kedalaman) - https://zubludiving.com/destination/indonesia/kalimantan/derawan-sangalaki-maratua', 'GoAsia (bulan terbaik, 28 titik selam) - https://goasia.cc/en/article/derawan-islands-kalimantan', 'TripBase (biota) - https://www.tripbase.com/destinations/derawan-islands-indonesia/diving/', 'Bluewater Dive Travel (suhu air) - https://www.bluewaterdivetravel.com/destination/derawan-islands-diving', 'Liveaboard.com: Derawan (arus) - https://www.liveaboard.com/diving/indonesia/derawan?cid=7792']::text[], 'https://www.iwarebatik.org/wp-content/uploads/2019/11/pulau-derawan-1.jpg', null, null, 'https://www.iwarebatik.org/derawan-island-marine-conservation-site-tourism/?lang=id'),
  ('weh', 'Pulau Weh', 'Aceh', 'menengah', 'Ulasan penyelam menyebut dinding curam dan arus kuat, sementara Wikivoyage menyebut ada pilihan untuk semua level. Estimasi tim, perlu ditinjau.', array['scuba', 'snorkeling']::text[], 'Pulau gunung api di ujung barat Indonesia dengan dinding karang dan arus yang menantang.', 'Pulau Weh adalah pulau vulkanik kecil di barat laut Sumatra yang juga dikenal sebagai Sabang, nama kota di ujung timur lautnya. Luas wilayahnya 122,13 km2 termasuk beberapa pulau kecil di sekelilingnya. Titik paling barat Indonesia ada di pulau ini, dan jaraknya hanya sekitar 15 km dari Banda Aceh.

Topografi vulkaniknya berlanjut sampai ke bawah air. Penyelam menemukan dinding batu curam yang disapu arus kuat dan dihuni ikan-ikan besar, yang menurut ulasan penyelam menantang namun memuaskan. Pulau Rubiah, salah satu dari empat pulau kecil di sekitar Weh, terkenal untuk wisata selam dan snorkeling berkat terumbu karangnya, dan Desa Iboih dikenal sebagai basis menyelam.

Pemerintah menetapkan sekitar 60 km2 darat dan laut di sekeliling pulau sebagai kawasan perlindungan satwa liar. Dari Banda Aceh, kapal cepat menyeberang sekitar satu jam dari Pelabuhan Ulee Lheue ke Balohan.', 'Kebanyakan titik mulai dangkal lalu menurun, kedalaman maksimum tercatat sekitar 31-40 m', 'April-Oktober (kemarau), paling stabil Mei-September', array['Hiu sirip hitam dan sirip putih', 'Hiu karang abu-abu', 'Hiu thresher (kadang)', 'Kipas gorgonia', 'Moray', 'Gurita', 'Lionfish', 'Ikan badut']::text[], 1500000, 5.82, 95.28, 'WIB', array['Wikipedia: Weh Island (koordinat, luas, Rubiah, Iboih) - https://en.wikipedia.org/wiki/Weh_Island', 'Wikivoyage: Sabang (snorkeling dan selam, titik paling barat) - https://en.wikivoyage.org/wiki/Sabang_(Indonesia)', 'Sea-Seek (kawasan perlindungan satwa liar 60 km2) - https://www.sea-seek.com/fr/Pulau-Weh-N-Sumatra-', 'Bluewater Dive Travel (ulasan: dinding curam, arus kuat) - https://www.bluewaterdivetravel.com/Pulau-Weh/coendozn', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Underwater Asia: Pulau Weh (musim, hiu) - https://underwaterasia.info/indonesia/pulau-weh-diving', 'PADI: Sumatra (Batee Tokong, hiu) - https://blog.padi.com/diving-the-best-sites-in-sumatra-indonesia/', 'Stingy Nomads (log kedalaman, biota) - https://stingynomads.com/diving-pulau-weh-indonesia/', 'Ocean Earth Travels (musim stabil) - https://www.oceanearthtravels.com/hotels-resorts/the-pade-dive-resort', 'Scuba Diver Life (musim hujan) - https://scubadiverlife.com/best-scuba-diving-pulau-weh/']::text[], 'https://okuselatan.disway.id/upload/35a83374bdf1245f05b6bde5085ac7ba.jpg', null, null, 'https://okuselatan.disway.id/traveling/read/640498/pulau-weh-pesona-keindahan-alami-yang-memikat-di-aceh'),
  ('togean', 'Kepulauan Togean', 'Sulawesi Tengah', 'pemula', 'Titik selam untuk semua kemampuan dan arus ringan karena Teluk Tomini terlindung (Underwater Asia, Reconnect).', array['scuba', 'snorkeling']::text[], '56 pulau di Teluk Tomini dengan hamparan terumbu karang terluas di Indonesia.', 'Kepulauan Togean (juga ditulis Togian) terdiri dari 56 pulau dan banyak pulau kecil di Teluk Tomini, lepas pantai Sulawesi Tengah. Pulau-pulau terbesarnya adalah Batudaka, Togean, Talatako, Una-Una, Walea Bahi, Walea Kodi, dan Malenge. Letaknya di zona peralihan garis Wallace dan Weber, tepat di jantung Segitiga Terumbu Karang.

Sebagian kepulauan ini menjadi taman nasional pada 2004. Menurut data ASEAN, luas totalnya 365.241 hektare dengan 340.119 hektare di antaranya perairan. Taman nasional ini punya hamparan terumbu karang terawetkan terluas di Indonesia. Pada Juni 2019, UNESCO juga menetapkannya sebagai Cagar Biosfer Tojo Una-Una Togean, yang ke-15 di Indonesia.

Lokasi selam yang populer antara lain Pulau Kadidiri dan Una-Una. Di darat ada kepiting kelapa yang bisa tumbuh sampai 4 kg dan monyet tonkean. Akses dari daratan lewat Ampana atau Gorontalo dengan kapal, dan pada awal 2023 ada sekitar 20 resor di kepulauan ini.', 'Tebing curam dan ngarai, ada titik dalam (Dominic Rock) dan titik mudah (Taipi Wall)', 'Sepanjang tahun, terbaik April-November', array['Penyu', 'Pari elang', 'Napoleon wrasse', 'Bumphead parrotfish', 'Barakuda', 'Kuwe', 'Hiu karang', 'Moray', 'Nudibranch', 'Frogfish', 'Kuda laut', 'Kepiting kelapa', 'Monyet tonkean (di darat)']::text[], 2000000, -0.39167, 121.95778, 'WITA', array['Wikipedia: Togian Islands (koordinat, taman nasional, resor) - https://en.wikipedia.org/wiki/Togian_Islands', 'Wikipedia: Togean Island (terumbu karang terawetkan) - https://en.wikipedia.org/wiki/Togean_Island', 'ASEAN ENMAPS: Kepulauan Togean NP (luas, cagar biosfer) - https://enmaps.aseanbiodiversity.org/kepulauan-togean-national-park-ktnp/', 'National-Parks.org (lokasi selam Kadidiri dan Una-Una) - https://national-parks.org/indonesia/kepulaua-togean-national-park/', 'Wikivoyage: Togean Islands (kepiting kelapa, kapal dari Ampana) - https://en.wikivoyage.org/wiki/Togean_Islands', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Underwater Asia: Togian Islands (semua level, sepanjang tahun) - https://underwaterasia.info/indonesia/togian-islands-diving', 'Reconnect (April-November, arus ringan) - https://reconnect.id/post/best-time-to-dive-in-sulawesi-a-month-by-month-guide-to-visibility-currents-and', 'Stingy Nomads: Togian (biota Kadidiri dan Una-Una) - https://stingynomads.com/?p=1862', 'Starfish (kedalaman Una-Una) - https://www.starfish.ch/dive/Togian-Banggai.html', 'Mermaid Liveaboards (jumlah titik selam) - https://www.mermaid-liveaboards.com/itineraries/lembeh-togian-lembeh/']::text[], 'https://s-light.tiket.photos/t/01E25EBZS3W0FY9GTG6C42E1SE/rsfit1440960gsm/events/2023/11/07/2cf68360-ebff-4ee0-80b8-fb8bb2f1910e-1699347374366-feb019d967a4921ecc2f19954d3ee541.png', null, null, 'https://www.tiket.com/id-id/to-do/5d4n-togean-trip-by-travel-buddies'),
  ('lembeh', 'Selat Lembeh', 'Sulawesi Utara', 'menengah', 'Wikipedia menyebut Lembeh favorit penyelam berpengalaman, tetapi kedalaman umumnya dangkal (15-25 m). Estimasi tim, perlu ditinjau.', array['scuba']::text[], 'Ibu kota muck diving dunia, dengan biota langka dan unik yang sangat padat.', 'Selat Lembeh memisahkan Pulau Lembeh dari daratan Sulawesi, dekat kota Bitung di Sulawesi Utara. Panjangnya sekitar 16 km dan lebarnya hanya sekitar 1,2 km, tetapi 88 titik selam sudah ditemukan di perairan sempit ini.

Lembeh dijuluki ibu kota muck diving dunia dan surga fotografer makro. Muck diving adalah menyelam di dasar berpasir untuk mencari makhluk kecil yang unik. Di sini penyelam berburu frogfish, gurita langka, kuda laut, dan nudibranch, sampai gurita mimic, cumi flamboyan, dan mandarin fish yang sedang kawin. Kedalaman sebagian besar titik selam berkisar 15 sampai 25 meter.

Karena letaknya terlindung, menyelam bisa dilakukan sepanjang tahun dan jarang batal karena cuaca. Desember sampai Februari umumnya musim hujan, dan jarak pandang di sini memang tidak tinggi. Dari Manado, naik bus ke Bitung lalu menyeberang sekitar 15 menit dengan perahu. Banyak penyelam menggabungkan Lembeh dengan Bunaken dalam satu perjalanan.', 'Umumnya 15-25 m', 'Sepanjang tahun (Desember-Februari umumnya musim hujan)', array['Frogfish', 'Gurita mimic', 'Cumi flamboyan', 'Kuda laut', 'Nudibranch', 'Mandarin fish']::text[], 1500000, 1.433, 125.233, 'WITA', array['Wikipedia: Lembeh (koordinat, biota, cuaca) - https://en.wikipedia.org/wiki/Lembeh', 'WorldAtlas (88 titik selam, kedalaman, biota) - https://www.worldatlas.com/articles/where-is-the-lembeh-strait.html', 'Indonesia.travel (ukuran selat, akses dari Manado) - https://www.indonesia.travel/th/en/destinations/sulawesi/bitung/the-lembeh-strait', 'Liveaboard.com (muck diving, jarak dari Manado) - https://www.liveaboard.com/diving/indonesia/lembeh-strait?cid=7229', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).']::text[], 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/0f/2c/a8/e4/aerial-shot-of-resort.jpg?w=1400&h=-1&s=1', null, null, 'https://www.tripadvisor.co.id/Hotel_Review-g680020-d10520101-Reviews-Dive_Into_Lembeh-Bitung_North_Sulawesi_Sulawesi.html'),
  ('gili', 'Kepulauan Gili', 'Nusa Tenggara Barat', 'pemula', 'Dikenal sebagai tempat paling populer di Indonesia untuk belajar menyelam, walau arus bisa kuat di beberapa titik (Underwater Asia).', array['scuba', 'snorkeling']::text[], 'Tiga pulau kecil di barat laut Lombok dengan sekolah selam, patung bawah laut, dan suasana santai.', 'Gili Trawangan, Gili Meno, dan Gili Air adalah tiga pulau kecil di barat laut Lombok. Dalam bahasa Sasak, gili berarti pulau kecil, dan nama lokal ketiganya, Gili Indah, berarti pulau kecil yang indah. Bali berjarak sekitar 35 km di sebelah barat Gili Trawangan.

Setiap pulau punya karakter sendiri. Gili Trawangan paling besar dan paling ramai, dengan banyak sekolah selam, dan satu-satunya yang naik sekitar 30 meter dari permukaan laut. Gili Meno terkecil dan paling tenang, bisa dikelilingi dengan jalan kaki sekitar satu jam. Gili Air paling dekat dengan Lombok dan berada di antara keduanya, ramai tapi tidak sehiruk-pikuk Trawangan. Namanya berasal dari fakta bahwa hanya pulau ini yang punya air tawar bawah tanah.

Di Gili Trawangan, pusat selam menawarkan kursus PADI dari Discover Scuba Diving sampai program instruktur, jadi ini tempat yang pas untuk mencoba menyelam pertama kali. Di dekat Gili Meno ada patung bawah laut bernama Nest yang kini menjadi rumah biota laut. Dari Bali, kapal cepat berangkat dari Padang Bai atau Sanur.', 'Titik pemula dangkal mulai sekitar 5 m, titik dalam sampai 30-40 m', 'April-Oktober (kemarau), bisa sepanjang tahun', array['Penyu hijau dan sisik', 'Hiu karang sirip hitam dan putih', 'Pari manta (akhir tahun)', 'Pari elang', 'Bumphead parrotfish', 'Moray', 'Nudibranch', 'Ikan kelelawar', 'Ikan badut']::text[], 1200000, -8.35, 116.06, 'WITA', array['Wikipedia: Gili Islands (koordinat, nama, ukuran) - https://en.wikipedia.org/wiki/Gili_Islands', 'Indonesia.travel (karakter tiga pulau, sekolah selam) - https://www.indonesia.travel/jp/ja/yacht/marina/medana-bay-lombok', 'Gili IDC (kursus PADI) - https://www.giliidc.com/?p=227', 'Quotidiano (patung bawah laut Nest) - https://www.quotidiano.net/itinerari/viaggi/estero/gili-isole-oceano-indiano-ls089ec1', 'DirectFerries (kapal dari Padang Bai/Sanur, keliling pulau) - https://www.directferries.de/blog/reisefuehrer-gili-inseln-anreise-und-aktivitaeten', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Manta Dive (musim, titik pemula, kedalaman) - https://manta-dive.com/diving-the-gilis/gili-dive-sites/', 'PADI: Top 8 Dive Sites Gili (Halik Reef, biota) - https://blog.padi.com/top-8-dive-sites-in-gili-islands-indonesia/', 'DiveSSI: Gili (kedalaman) - https://www.divessi.com/en/blog/best-diving-in-gili-island-9011.html', 'Underwater Asia: Lombok dan Gili (tempat belajar menyelam) - https://www.underwaterasia.info/indonesia/lombok-gili-islands-diving']::text[], 'https://image.idntimes.com/post/20220211/33727847-149966089196156-7904293099562598400-n-3f470419c48481a410869607195370a0-ad36f8a8b83f99e6c7e4c8a82f129f3f.jpg?tr=w-1200,f-webp,q-75&width=1200&format=webp&quality=75', null, null, 'https://ntb.idntimes.com/travel/destination/gili-meno-wisata-eksotis-yang-menenangkan-di-lombok-utara-00-lm183-m47mtn'),
  ('nusa-penida', 'Nusa Penida', 'Bali', 'menengah', 'Sebagian besar titik selam berarus cukup kuat, tetapi Crystal Bay ramah pemula (Liveaboard.com, BaliOcean). Estimasi tim, perlu ditinjau.', array['scuba', 'snorkeling']::text[], 'Tempat bertemu pari manta, dan mola mola di musimnya, hanya sekitar 15 km dari Bali.', 'Nusa Penida adalah pulau di tenggara Bali yang dipisahkan Selat Badung, sekitar 15 km dari daratan Bali. Pulau ini sekaligus kecamatan di Kabupaten Klungkung yang mencakup Nusa Lembongan, Nusa Ceningan, dan pulau-pulau kecil lain. Dibanding Bali, pulaunya lebih kering, dan bersama Lembongan serta Ceningan, pulau ini menjadi cagar burung.

Di bawah air ada beberapa titik selam yang bisa dipilih. Manta Point terkenal karena pari manta datang ke sana untuk dibersihkan dan bisa dijumpai hampir sepanjang tahun. Crystal Bay punya air sangat jernih dan sering disebut ramah untuk pemula, juga tempat melihat mola mola atau ikan matahari raksasa, terutama saat air lebih dingin sekitar Juli sampai Oktober. Toya Pakeh dikenal sebagai salah satu wall dive terbaik, sementara Batu Meling, Batu Abah, dan Malibu Point melengkapi pilihan lain.

Perlu diingat, sebagian besar titik selam punya arus yang cukup kuat dan kadang tak terduga. Di Manta Point suhu air bisa turun ke sekitar 20 sampai 24 derajat Celsius. Kapal liveaboard dari Benoa atau Sanur butuh sekitar dua jam ke pulau ini.', 'Titik populer sekitar 5-40 m (Crystal Bay sampai 60 m lebih)', 'April-Oktober, pari manta hampir sepanjang tahun, mola mola sekitar Juli-Oktober', array['Pari manta (sayap sampai 4-5 m)', 'Mola mola (ikan matahari)', 'Hiu paus (jarang, setelah November)', 'Penyu', 'Karang keras dan lunak']::text[], 1200000, -8.73333, 115.53333, 'WITA', array['Wikipedia: Nusa Penida (koordinat, titik selam, cagar burung) - https://en.wikipedia.org/wiki/Nusa_Penida', 'Liveaboard.com (manta, mola mola, arus) - https://www.liveaboard.com/diving/indonesia/nusa-penida?CID=7796', 'BaliOcean (Crystal Bay ramah pemula) - https://www.baliocean.com/?p=25919', 'Bali Fun Diving (suhu air, Manta Point) - https://balifundiving.com/experience-diving-in-nusa-penida/', 'Indonesia.travel (spot snorkeling) - https://www.indonesia.travel/sa-en/destination/bali-nusa-tenggara/bali/snorkeling-nusa-penida', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Abyss Ocean World (kedalaman titik selam) - https://abyssoceanworld.com/?p=9996', 'GetMyBoat (manta, hiu paus, arus Crystal Bay) - https://www.getmyboat.com/trips/VYm1Jk7Y/', 'Bali Fun Diving (musim, mola mola) - https://balifundiving.com/?p=12148', 'BaliOcean (Blue Corner, Crystal Bay) - https://www.baliocean.com/dive-sites/nusa-penida/']::text[], 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Broken_Beach.jpg/960px-Broken_Beach.jpg?utm_source=id.wikipedia.org&utm_campaign=parser&utm_content=thumbnail', null, null, 'https://id.wikipedia.org/wiki/Nusa_Penida'),
  ('tulamben', 'Tulamben (USAT Liberty)', 'Bali', 'pemula', 'Wikipedia menyebut bangkai kapalnya cocok untuk penyelam semua tingkat sertifikasi.', array['scuba', 'snorkeling']::text[], 'Menyelam ke bangkai kapal Perang Dunia II yang bisa dijangkau langsung dari pantai.', 'Tulamben adalah desa nelayan kecil di pantai timur laut Bali. Daya tarik utamanya adalah USAT Liberty, kapal kargo Angkatan Darat Amerika yang ditorpedo kapal selam Jepang pada Januari 1942 lalu dikandaskan di sini agar muatannya bisa diselamatkan. Pada 1963, letusan Gunung Agung menggeser kapal itu ke laut, dan sejak itu karang tumbuh menutupinya.

Bangkai kapal sepanjang sekitar 125 meter ini terbaring tidak jauh dari pantai berbatu, cukup berenang singkat dari tepi pantai. Bagian tertingginya sekitar 5 meter dari permukaan dan yang terdalam sekitar 30 meter, jadi cocok untuk penyelam semua tingkat sertifikasi dan juga snorkeling. Airnya hangat, sekitar 28 sampai 30 derajat Celsius. Di sekitar bangkai kapal ada kawanan kuwe, bream, fusilier, dan anthias, ditambah ikan bumphead parrotfish, napoleon wrasse, dan barakuda. Di dekatnya ada zona Coral Garden pada kedalaman 4 sampai 25 meter, dan di kedalaman 15 meter ada pura kecil di bawah laut.

Kondisi selam terbaik biasanya pada Oktober dan November. Pada musim tertentu, mola mola, hiu paus, dan hiu sirip hitam sering mampir. Di musim ramai, sampai 100 penyelam turun ke bangkai kapal setiap hari.', 'Sekitar 5-30 m', 'Oktober-November (kondisi paling tenang)', array['Kawanan kuwe, bream, fusilier, anthias', 'Bumphead parrotfish', 'Napoleon wrasse', 'Barakuda', 'Mola mola dan hiu paus (musim tertentu)']::text[], 1200000, -8.27441, 115.5949, 'WITA', array['Wikipedia: Tulamben (musim, tingkat sertifikasi, pura bawah laut) - https://en.wikipedia.org/wiki/Tulamben', 'Wikipedia: USAT Liberty (ukuran, kedalaman, koordinat OpenStreetMap) - https://en.wikipedia.org/wiki/USAT_Liberty', 'Tulamben Wreck Divers (biota di bangkai kapal) - https://www.tulambenwreckdivers.com/Liberty-Wreck', 'BaliOcean (suhu air, semua level) - https://www.baliocean.com/blog/usat-liberty-wreck-tulamben-bali/', 'Pacific Wrecks (riwayat kapal) - https://pacificwrecks.com/ship/usat/liberty.html', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).']::text[], 'https://lovebali.baliprov.go.id/storage/touriest_destinations/img-165828977362d77e6d10be9.jpg', null, null, 'https://lovebali.baliprov.go.id/destination/detail/34/tulamben'),
  ('cenderawasih', 'Teluk Cenderawasih', 'Papua', 'menengah', 'Estimasi sementara tim, belum ada sumber penilaian level. Perlu ditinjau.', array['scuba', 'snorkeling']::text[], 'Taman nasional laut terbesar Indonesia, tempat berenang bersama hiu paus di bawah bagan nelayan.', 'Taman Nasional Teluk Cenderawasih adalah taman nasional laut terbesar di Indonesia, di tenggara Semenanjung Kepala Burung, Papua. Luasnya sekitar 14.535 km2 atau sekitar 1,4 juta hektare yang mencakup dua kabupaten, Nabire di Papua dan Teluk Wondama di Papua Barat. Taman ini ditetapkan lewat SK Menteri Kehutanan pada 29 Agustus 2002.

Daya tarik utamanya adalah hiu paus. Di sekitar Teluk Kwatisore, di selatan taman, ada sekitar 23 bagan atau platform penangkap ikan yang menurut nelayan didatangi hiu paus sepanjang tahun untuk menyedot ikan kecil dari jaring. Perilaku ini tercatat pertama kali di dunia di sini. Sampai Agustus 2023 ada 188 hiu paus yang teridentifikasi. Pengunjung diminta mengikuti kode etik, termasuk tidak memakai blitz kamera karena bisa mengganggu hiu.

Selain hiu paus, perairannya dihuni dugong, lumba-lumba, dan ikan karang seperti ikan badut dan ikan kupu-kupu. Kebanyakan wisatawan asing datang lewat kapal liveaboard. Pengunjung bisa terbang ke Biak, dan dari Nabire perjalanan ke taman sekitar tiga jam dengan speedboat.', 'Sekitar 5-40 m', 'Hiu paus ada sepanjang tahun, paling banyak diselami Juni-Oktober', array['Hiu paus', 'Penyu (sisik, hijau, lekang, belimbing)', 'Dugong', 'Lumba-lumba', 'Ikan badut', 'Ikan kupu-kupu', 'Bangkai kapal Perang Dunia II']::text[], 3000000, -2.5, 134.633, 'WIT', array['Wikipedia: Teluk Cenderawasih National Park (koordinat, luas, biota) - https://en.wikipedia.org/wiki/Teluk_Cenderawasih_National_Park', 'Antara News (SK 2002, jumlah hiu paus 2023) - https://en.antaranews.com/news/295338/a-massive-undertaking-to-protect-whale-sharks-in-indonesia', 'Divers Alert Network (bagan Kwatisore, perilaku hiu paus) - https://dan.org/alert-diver/article/cenderawasih-bay/', 'Jakarta Post (kode etik, wisatawan) - https://www.thejakartapost.com/news/2017/05/30/whale-sharks-draw-tourists-nabire', 'Jakarta Post (luas, akses) - https://www.thejakartapost.com/travel/2017/05/13/cenderawasih-bay-a-haven-for-whale-shark-enthusiasts', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Bluewater Dive Travel: Cenderawasih (kedalaman, musim) - https://www.bluewaterdivetravel.com/cenderawasih-bay-diving', 'Liveaboard.com: Cenderawasih (musim liveaboard, penyu) - https://www.liveaboard.com/diving/indonesia/cenderawasih-bay/scuba', 'PADI: Whale Shark Diving (Kwatisore, Juni-Oktober) - https://blog.padi.com/tw/whale-shark-diving-the-best-dive-sites-in-the-world/']::text[], 'https://genpi.id/wp-content/uploads/2020/09/WhatsApp-Image-2020-09-11-at-3.37.34-PM.jpeg', null, null, 'https://genpi.id/teluk-cenderawasih-surga-bawah-laut-papua/'),
  ('banda', 'Kepulauan Banda', 'Maluku', 'menengah', 'Sebagian besar titik cocok untuk semua level, kecuali beberapa yang berarus kuat dan hanya untuk penyelam lanjut (Bluewater Dive Travel, Ocean Earth Travels).', array['scuba', 'snorkeling']::text[], 'Pulau rempah dengan gunung api aktif, aliran lava yang kini jadi taman karang, dan gunung laut hiu martil.', 'Kepulauan Banda di Maluku terdiri dari 11 pulau, tujuh di antaranya berpenghuni, dengan sekitar 20.900 penduduk (Sensus 2020). Sampai pertengahan abad ke-19, kepulauan ini adalah satu-satunya penghasil pala dan fuli di dunia. Kebun pala dan kenari masih menaungi bukit-bukitnya, dan Banda Neira sebagai kota utama menyimpan bangunan bergaya kolonial serta museum yang bercerita tentang sejarah rempah.

Gunung Api, gunung berapi aktif setinggi sekitar 650 meter, menjulang tepat di sebelah Banda Neira. Letusan 1988 mengalirkan lava ke laut, dan kini aliran lava itu dihuni karang keras yang tumbuh sangat cepat. Titik selamnya dikenal dengan nama Lava Flows. Di perairan lepas, penyelam bisa bertemu tuna, tuna gigi anjing, kawanan kuwe, ular laut di Manuk, dan hiu martil di gunung laut.

Musim selamnya singkat, kira-kira Maret sampai April dan September sampai November, mengikuti jendela penyeberangan kapal. Di Banda Neira ada operator selam yang buka saat musim.', 'Sekitar 5-40 m (dinding di Pulau Ai turun sampai 60 m)', 'Sekitar Maret-April dan September-November', array['Tuna', 'Tuna gigi anjing', 'Kawanan fusilier', 'Ikan pemicu gigi merah', 'Ular laut (Manuk)', 'Hiu martil', 'Mandarinfish', 'Honeycomb moray', 'Karang keras di aliran lava']::text[], 3000000, -4.583, 129.917, 'WIT', array['Wikipedia: Banda Islands (jumlah pulau, pala, gunung api) - https://en.wikipedia.org/wiki/Banda_Islands', 'Wikipedia: Banda Neira (kaldera terendam) - https://en.wikipedia.com/wiki/Bandanaira', 'Ocean Earth Travels (lava 1988, musim selam, hiu martil) - https://www.oceanearthtravels.com/destinations/banda-sea/', 'Indo Pacific Images (Lava Flows, operator selam) - https://indopacificimages.com/?p=42334', 'YIT (satwa laut lepas, bangunan kolonial, museum) - https://www.yit.nz/node/66431', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Emperor Divers (kedalaman, visibilitas, suhu) - https://emperordivers.com/banda-islands-part-3', 'Bluewater Dive Travel: Banda Sea (level, arus) - https://www.bluewaterdivetravel.com/banda-sea-diving', 'Dive The World: Banda (Pulau Ai, dinding 60 m) - https://dive-the-world.com/diving-sites-indonesia-banda-islands.php']::text[], 'https://econusa.id/wp-content/uploads/2023/10/banda-1536x1151.webp', null, null, 'https://econusa.id/id/ecodefender/keistimewaan-kepulauan-banda/'),
  ('menjangan', 'Pulau Menjangan', 'Bali', 'menengah', 'Penyelam perlu sertifikasi dasar (Bali Fun Diving), kondisinya disebut mudah (Lloyd Borrett). Estimasi tim, perlu ditinjau.', array['scuba']::text[], 'Lokasi selam pertama Bali yang terkenal di dunia, dengan dinding karang dan jarak pandang lebih dari 50 meter.', 'Pulau Menjangan adalah pulau kecil sekitar 5 mil di barat laut Bali, bagian dari Taman Nasional Bali Barat dan masuk wilayah Buleleng. Menjangan berarti rusa, nama yang diberikan warga setempat setelah melihat kawanan rusa berenang ke pulau ini tiap musim semi. Di pulau ada dermaga, tiga pura Hindu, dan satwa seperti rusa, kelinci liar, biawak, dan ayam hutan.

Menjangan lazim disebut lokasi selam pertama di Bali yang terkenal secara internasional, dan terumbunya termasuk yang paling terjaga di kawasan itu. Dindingnya turun dari 10 sampai 60 meter lebih, penuh celah dan overhang dengan karang lunak, spons, dan kipas gorgonia terbanyak di Bali, kadang dengan kuda laut pigmi di dalamnya. Airnya hangat dengan jarak pandang bisa melewati 50 meter, dan kondisinya relatif mudah untuk wall diving. Di kedalaman 45 meter ada bangkai kapal Anchor yang tertutup karang lunak.

Hiu paus kadang terlihat, tetapi satwa pelagis agak jarang karena pulau ini terlindung dari arus dingin. Perjalanan dari daratan Bali sekitar 30 menit dengan perahu, dan semua toko selam di sekitar mengatur trip harian. Kondisinya bagus sepanjang tahun, dengan jarak pandang dan cuaca terbaik biasanya April sampai November. Penyelam perlu punya sertifikasi dasar.', 'Dinding 10 m sampai lebih dari 60 m', 'April-November (jarak pandang dan cuaca terbaik)', array['Kipas gorgonia', 'Kuda laut pigmi', 'Karang lunak', 'Spons', 'Penyu', 'Hiu paus (kadang)']::text[], 1200000, -8.09604, 114.51489, 'WITA', array['Wikipedia: Menjangan Island (lokasi, nama, satwa, terumbu) - https://en.wikipedia.org/wiki/Menjangan_Island', 'Indonesia.travel (wall diving, bangkai kapal Anchor) - https://www.indonesia.travel/in-en/destination/bali-nusa-tenggara/bali/bali---menjangan-island', 'Lloyd Borrett (jarak pandang, gorgonia, pelagis) - https://www.borrett.id.au/divelog/divecity.php?id=40', 'Bali Fun Diving (sertifikasi, musim terbaik) - https://balifundiving.com/bali-dive-sites/menjangan-island/', 'Zona waktu: ditentukan dari provinsi (aturan zona waktu Indonesia).', 'Koordinat Pulau Menjangan diisi manual oleh tim (cocokkan dengan peta).']::text[], 'https://balifundiving.com/wp-content/uploads/2025/05/menjangan-island-diving.webp', null, null, 'https://balifundiving.com/id/situs-menyelam-di-bali/pulau-menjangan/')
